  ('pt-BR', 'mods.skillsInvalid', $json$"{name}: este JayV não consegue ler as skills que o catálogo descreve. Atualize o app."$json$::jsonb),
  ('en', 'mods.skillsInvalid', $json$"{name}: this JayV can't read the skills the catalog describes. Update the app."$json$::jsonb),
  ('es', 'mods.skillsInvalid', $json$"{name}: este JayV no puede leer las skills que describe el catálogo. Actualiza la app."$json$::jsonb),
  ('zh-CN', 'mods.skillsInvalid', $json$"{name}：此版本的 JayV 无法读取目录描述的技能。请更新应用。"$json$::jsonb),
  ('hi', 'mods.skillsInvalid', $json$"{name}: यह JayV कैटलॉग में बताई गई स्किल पढ़ नहीं सकता। ऐप अपडेट करें।"$json$::jsonb),
  ('ar', 'mods.skillsInvalid', $json$"{name}: لا يستطيع هذا الإصدار من JayV قراءة المهارات التي يصفها الفهرس. حدّث التطبيق."$json$::jsonb),
  ('fr', 'mods.skillsInvalid', $json$"{name} : ce JayV ne sait pas lire les skills que décrit le catalogue. Mettez l’app à jour."$json$::jsonb),
  ('ru', 'mods.skillsInvalid', $json$"{name}: эта версия JayV не может прочитать скиллы, описанные в каталоге. Обновите приложение."$json$::jsonb),
  ('ja', 'mods.skillsInvalid', $json$"{name}: この JayV はカタログに書かれたスキルを読み込めません。アプリを更新してください。"$json$::jsonb),
  ('de', 'mods.skillsInvalid', $json$"{name}: Dieses JayV kann die Skills, die der Katalog beschreibt, nicht lesen. Aktualisieren Sie die App."$json$::jsonb),
  ('pt-BR', 'mods.skillTaken', $json$"Outro mod já traz a skill {name}."$json$::jsonb),
  ('en', 'mods.skillTaken', $json$"Another mod already brings the skill {name}."$json$::jsonb),
